100	
101	DHTBucketTreeNode* findTreeNodeFor(DHTBucketTreeNode* root,
102	                                   const unsigned char* key)
103	{
104	  if (root->leaf()) {
105	    return root;
106	  }
107	  else {
108	    return findTreeNodeFor(root->dig(key), key);
109	  }
110	}
111	
112	std::shared_ptr<DHTBucket> findBucketFor(DHTBucketTreeNode* root,
113	                                         const unsigned char* key)
114	{
115	  DHTBucketTreeNode* leaf = findTreeNodeFor(root, key);
116	  return leaf->getBucket();
117	}
118	
119	namespace {
120	void collectNodes(std::vector<std::shared_ptr<DHTNode>>& nodes,
121	                  const std::shared_ptr<DHTBucket>& bucket)
122	{
123	  std::vector<std::shared_ptr<DHTNode>> goodNodes;
124	  bucket->getGoodNodes(goodNodes);
125	  nodes.insert(nodes.end(), goodNodes.begin(), goodNodes.end());
126	}
127	} // namespace
128	
129	namespace {
130	void collectDownwardLeftFirst(std::vector<std::shared_ptr<DHTNode>>& nodes,
131	                              DHTBucketTreeNode* tnode)
132	{
133	  if (tnode->leaf()) {
134	    collectNodes(nodes, tnode->getBucket());
135	  }
136	  else {
137	    collectDownwardLeftFirst(nodes, tnode->getLeft());
138	    if (nodes.size() < DHTBucket::K) {
139	      collectDownwardLeftFirst(nodes, tnode->getRight());
140	    }
141	  }
142	}
143	} // namespace
144	
145	namespace {
146	void collectDownwardRightFirst(std::vector<std::shared_ptr<DHTNode>>& nodes,
147	                               DHTBucketTreeNode* tnode)
148	{
149	  if (tnode->leaf()) {
150	    collectNodes(nodes, tnode->getBucket());
151	  }
152	  else {
153	    collectDownwardRightFirst(nodes, tnode->getRight());
154	    if (nodes.size() < DHTBucket::K) {
155	      collectDownwardRightFirst(nodes, tnode->getLeft());
156	    }
157	  }
158	}
159	} // namespace
160	
161	namespace {
162	void collectUpward(std::vector<std::shared_ptr<DHTNode>>& nodes,
163	                   DHTBucketTreeNode* from)
164	{
165	  while (1) {
166	    DHTBucketTreeNode* parent = from->getParent();
167	    if (!parent) {
168	      break;
169	    }
170	    if (parent->getLeft() == from) {
171	      collectNodes(nodes, parent->getRight()->getBucket());
172	    }
173	    else {
174	      collectNodes(nodes, parent->getLeft()->getBucket());
175	    }
176	    from = parent;
177	    if (DHTBucket::K <= nodes.size()) {
178	      break;
179	    }
180	  }
181	}
182	} // namespace
183	
184	void findClosestKNodes(std::vector<std::shared_ptr<DHTNode>>& nodes,
185	                       DHTBucketTreeNode* root, const unsigned char* key)
186	{
187	  size_t nodesSize = nodes.size();
188	  if (DHTBucket::K <= nodesSize) {
189	    return;
190	  }
191	  DHTBucketTreeNode* leaf = findTreeNodeFor(root, key);
192	  if (leaf == root) {
193	    collectNodes(nodes, leaf->getBucket());
194	  }
195	  else {
196	    DHTBucketTreeNode* parent = leaf->getParent();
197	    if (parent->getLeft() == leaf) {
198	      collectDownwardLeftFirst(nodes, parent);
199	    }
200	    else {
201	      collectDownwardRightFirst(nodes, parent);
202	    }
203	    if (nodes.size() < DHTBucket::K) {
204	      collectUpward(nodes, parent);
205	    }
206	  }
207	  if (DHTBucket::K < nodes.size()) {
208	    nodes.erase(nodes.begin() + DHTBucket::K, nodes.end());
209	  }
210	}
211	
212	void enumerateBucket(std::vector<std::shared_ptr<DHTBucket>>& buckets,
213	                     DHTBucketTreeNode* root)
214	{
215	  if (root->leaf()) {
216	    buckets.push_back(root->getBucket());
217	  }
218	  else {
219	    enumerateBucket(buckets, root->getLeft());
220	    enumerateBucket(buckets, root->getRight());
221	  }
222	}
223	
224	} // namespace dht
225	
226	} // namespace aria2
