59	DHTAutoSaveCommand::DHTAutoSaveCommand(cuid_t cuid, DownloadEngine* e,
60	                                       int family,
61	                                       std::chrono::seconds interval)
62	    : TimeBasedCommand{cuid, e, std::move(interval)},
63	      family_{family},
64	      routingTable_{nullptr}
65	{
66	}
67	
68	DHTAutoSaveCommand::~DHTAutoSaveCommand() = default;
69	
70	void DHTAutoSaveCommand::preProcess()
71	{
72	  if (getDownloadEngine()->getRequestGroupMan()->downloadFinished() ||
73	      getDownloadEngine()->isHaltRequested()) {
74	    save();
75	    enableExit();
76	  }
77	}
78	
79	void DHTAutoSaveCommand::process() { save(); }
80	
81	void DHTAutoSaveCommand::save()
82	{
83	  std::string dhtFile = getDownloadEngine()->getOption()->get(
84	      family_ == AF_INET ? PREF_DHT_FILE_PATH : PREF_DHT_FILE_PATH6);
85	  A2_LOG_INFO(fmt("Saving DHT routing table to %s.", dhtFile.c_str()));
86	
87	  // Removing tempFile is unnecessary because the file is truncated on
88	  // open.  But the bug in 1.10.4 creates directory for this path.
89	  // Because it is directory, opening directory as file fails.  So we
90	  // first remove it here.
91	  File tempFile(dhtFile + "__temp");
92	  tempFile.remove();
93	
94	  File(File(dhtFile).getDirname()).mkdirs();
95	  std::vector<std::shared_ptr<DHTNode>> nodes;
96	  std::vector<std::shared_ptr<DHTBucket>> buckets;
97	  routingTable_->getBuckets(buckets);
98	  for (const auto& b : buckets) {
99	    std::vector<std::shared_ptr<DHTNode>> goodNodes;
100	    b->getGoodNodes(goodNodes);
101	    nodes.insert(nodes.end(), goodNodes.begin(), goodNodes.end());
102	  }
103	
104	  DHTRoutingTableSerializer serializer(family_);
105	  serializer.setLocalNode(localNode_);
106	  serializer.setNodes(nodes);
107	
108	  try {
109	    serializer.serialize(dhtFile);
110	  }
111	  catch (RecoverableException& e) {
112	    A2_LOG_ERROR_EX(fmt("Exception caught while saving DHT routing table to %s",
113	                        dhtFile.c_str()),
114	                    e);
115	  }
116	}
