118	void DHTAutoSaveCommand::setLocalNode(const std::shared_ptr<DHTNode>& localNode)
119	{
120	  localNode_ = localNode;
121	}
122	
123	void DHTAutoSaveCommand::setRoutingTable(DHTRoutingTable* routingTable)
124	{
125	  routingTable_ = routingTable;
126	}
